            app.CloseAllWindows();yield return null;stage.Open("photo");yield return new WaitForSeconds(.2f);editor=app.Windows.GetComponentInChildren<PhotoCorrectionRenderer>();var reward=editor.GetComponentsInChildren<Button>().Single(b=>b.name=="사진 보상");Check(!reward.interactable&&editor.RewardAlpha==0&&string.IsNullOrEmpty(editor.Loaded),"완료 후에도 재열기는 빈 화면");editor.Load("photo"+stage.Randoms.Frequency);Check(reward.interactable,"정답 사진 다시 열면 미획득 보상 회수 가능");
            int sounds=0;System.Action<string> heard=key=>{if(key=="sfx_photo_success")sounds++;};app.Audio.Played+=heard;yield return MouseClick((RectTransform)reward.transform);editor.CollectReward();editor.CollectReward();yield return new WaitForSeconds(.3f);app.Audio.Played-=heard;
            Check(stage.PhotoRewardClaimed&&stage.Files.Find("iconA").available&&sounds==1&&!reward.GetComponent<Image>().raycastTarget&&reward.GetComponent<Image>().color.a==0,"보상 클릭 1회 지급·효과음 1회·페이드 제거");
            var disk=new SaveService().Progress.stage05;Check(disk.photoSolved&&disk.photoRewardClaimed,"완료·획득 독립 저장");Capture("stage05-photo");app.CloseAllWindows();yield return null;
        }
        IEnumerator S5Playlist(Stage05Controller stage,bool realDrop)
        {
            stage.Open("classic");stage.Open("classic");Check(!app.Windows.GetComponentsInChildren<FakeWindow>().Any(w=>w.Key=="s5:file:classic"),"classic 클릭·재클릭 재생창 없음");
            stage.Open("sound");yield return new WaitForSeconds(.2f);Check(!stage.PlaylistSolved,"채우기 전 목록 미해결");
            stage.Drop("classic","s5:hint");Check(!stage.ClassicRegistered,"빈 슬롯 외 classic 드롭 무효");if(realDrop){var icon=Icons().Single(i=>i.Id=="s5:classic");var slot=app.Windows.GetComponentsInChildren<DropTarget>().Single(t=>t.Category=="s5:slot");yield return MouseDrag(Center(icon.Rect),Center((RectTransform)slot.transform));}else stage.RegisterClassic("classic");
            Check(stage.Files.Find("classic")==null&&!Icons().Any(i=>i.Id=="s5:classic")&&stage.Playlist.Contains(stage.Data.classicSong)&&new SaveService().Progress.stage05.files.All(n=>n.id!="classic"),"classic 등록 후 파일 완전 제거·리스트 곡 정보 및 저장 유지");
            Check(stage.ClassicRegistered&&!stage.PlaylistSolved&&!stage.RegisterClassic("classic"),"빈 슬롯 실제 드롭·중복 금지·채우기만으로 미해결");
            for(int i=0;i<10;i++){int at=stage.Playlist.IndexOf(stage.Randoms.Hint[i]);while(at>i){stage.MoveSong(at,-1);at--;}}
            app.Windows.GetComponentInChildren<PlaylistView>().Draw();Check(stage.PlaylistSolved&&!stage.PlaylistRewardClaimed&&!stage.Files.Find("iconB").available,"10곡 정렬 완료·클릭 전 B 미지급");
            var saved=new SaveService().Progress.stage05;Check(saved.playlistSolved&&!saved.playlistRewardClaimed,"리스트 완료·미획득 별도 저장");
            app.CloseAllWindows();yield return null;stage.Open("sound");yield return new WaitForSeconds(.2f);var view=app.Windows.GetComponentInChildren<PlaylistView>();var reward=view.GetComponentsInChildren<Button>().Single(b=>b.name=="리스트 보상");
            Check(reward.interactable&&!view.GetComponentsInChildren<TMP_Text>().Any(t=>t.text=="[열림]"),"재열기 열림 글씨 대신 미획득 아이콘");Capture("stage05-playlist-pending");
            int sounds=0;Action<string> heard=k=>{if(k=="sfx_playlist_success")sounds++;};app.Audio.Played+=heard;yield return MouseClick((RectTransform)reward.transform);view.CollectReward();view.CollectReward();yield return new WaitForSeconds(.3f);app.Audio.Played-=heard;
            Check(stage.PlaylistRewardClaimed&&stage.Files.Find("iconB").available&&sounds==1&&reward.GetComponent<Image>().color.a==0&&!reward.interactable,"B 실제 클릭 1회 지급·음향 1회·페이드 제거");Check(new SaveService().Progress.stage05.playlistRewardClaimed,"B 획득 저장");var before=string.Join(",",stage.Playlist);stage.MoveSong(0,1);Check(before==string.Join(",",stage.Playlist),"해결 후 목록 잠금");Capture("stage05-playlist");app.CloseAllWindows();yield return null;
        }
