        {
            var a=Icons().Single(i=>i.Id=="s5:iconA");var b=Icons().Single(i=>i.Id=="s5:iconB");yield return MouseDrag(Center(a.Rect),Center(b.Rect));yield return new WaitForSeconds(.8f);Check(stage.Files.Find("door").available&&!stage.Files.Find("iconA").available&&!stage.Files.Find("iconB").available,"양방향 반쪽 결합·소비·문 생성");stage.Open("door");yield return null;Check(app.Windows.GetComponentInChildren<ImageViewer>(),"door.png는 이미지 뷰어");app.CloseAllWindows();yield return null;stage.Drop("door","s5trash");Check(!stage.Files.CanUse(stage.Files.Find("door")),"문 휴지통 실행 차단");stage.Files.RestoreTrash(stage.Files.Find("door"));stage.Rename("door","door.xyz");Check(stage.Files.Find("door").isBroken,"잘못된 확장자 깨짐");stage.Files.RestoreOriginal(stage.Files.Find("door"));Check(stage.Files.Find("door").displayName=="door.png","깨진 문 원본 복원");stage.Rename("door","wrong.exe");stage.Open("door");Check(!app.Dialogue.Active&&!stage.FinalDone,"틀린 exe 이름은 탈출 불가");app.CloseAllWindows();yield return null;
            stage.Rename("door"," DoOr.ExE ");Check(app.Dialogue.CurrentSequence=="S5_FINAL"&&!stage.Ready,"대소문자 이름 변경 즉시 마지막 대화·입력 차단");yield return Hold(Key.LeftCtrl,7);Check(stage.FinalDone,"마지막 대화 완료 실행 해금");stage.Talk();Check(app.Dialogue.CurrentSequence=="S5_AFTER_FINAL","마지막 이후 점만 반복");yield return Hold(Key.LeftCtrl,1);stage.Open("door");yield return new WaitForSeconds(12);Check(app.Stages.Current.stageId=="Stage06"&&app.Save.Progress.cleared.Contains("Stage05"),"Stage05 CMD 클리어 저장·Stage06 연결");
        }
